public class NestedInteger {
    private readonly int? _value; private readonly List<NestedInteger> _list;
    public NestedInteger(int value) { _value = value; }
    public NestedInteger(params NestedInteger[] items) { _list = items.ToList(); }
    public bool IsInteger() => _value.HasValue;
    public int GetInteger() => _value ?? throw new InvalidOperationException("not an integer");
    public IList<NestedInteger> GetList() => _list ?? throw new InvalidOperationException("not a list");
}

public static class NestedWeights {
    // Inverse depth weighting: weight = maxDepth - depth + 1. One BFS pass, no maxDepth needed:
    // carry the running sum of every level seen so far and add it once per level.
    public static int DepthSumInverse(IList<NestedInteger> nestedList) {
        if (nestedList == null) return 0;
        var queue = new Queue<NestedInteger>(nestedList);
        int levelSum = 0, total = 0, answer = 0;
        while (queue.Count > 0) {
            int size = queue.Count; bool sawInteger = false;
            for (int i = 0; i < size; i++) {
                var ni = queue.Dequeue();
                if (ni.IsInteger()) { levelSum += ni.GetInteger(); sawInteger = true; }
                else foreach (var child in ni.GetList()) queue.Enqueue(child);
            }
            total += levelSum;
            // Levels holding only (empty) lists must not count toward maxDepth: the answer is the
            // total as of the deepest level that actually contained an integer.
            if (sawInteger) answer = total;
        }
        return answer;
    }

    // Forward depth weighting: weight = depth (top level is 1).
    public static int DepthSum(IList<NestedInteger> nestedList) {
        if (nestedList == null) return 0;
        var queue = new Queue<(NestedInteger N, int D)>(nestedList.Select(n => (n, 1)));
        int total = 0;
        while (queue.Count > 0) {
            var (n, d) = queue.Dequeue();
            if (n.IsInteger()) total += n.GetInteger() * d;
            else foreach (var c in n.GetList()) queue.Enqueue((c, d + 1));
        }
        return total;
    }
}
